#[no_mangle]
pub extern "C" fn longestpalindrome(v:*const i64,n:usize)->i64{if v.is_null()||n<1||n>65{return -1;}let v=unsafe{std::slice::from_raw_parts(v,n)};let count=v[0];if !(0..=64).contains(&count)||n!=count as usize+1{return -1;}let mut a=Vec::new();for &x in &v[1..]{if !(32..=126).contains(&x)||x==35{return -1;}if x!=32{a.push(x)}}let z=2*a.len()+1;let mut t=vec![-1i64;z];for i in 0..a.len(){t[2*i+1]=a[i];}let mut p=vec![0usize;z];let(mut center,mut right,mut best)=(0usize,0usize,0usize);for i in 0..z{if i<right{p[i]=p[2*center-i].min(right-i);}while i>=p[i]+1&&i+p[i]+1<z&&t[i-p[i]-1]==t[i+p[i]+1]{p[i]+=1;}best=best.max(p[i]);if i+p[i]>right{center=i;right=i+p[i];}}best as i64}
